{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.saadaa_po_otiff_report as with po_data as ( select po_ref_num, cast(po_id as string) po_id, vendor_name, vendor_code, po_created_date, expected_delivery_date, po_original_quantity, grn_receive_quantity, po_pending_quantity, po_status, last_grn_date, case when date(expected_delivery_date) is null then cast(null as string) when date(last_grn_date) <= date(expected_delivery_date) then \'yes\' else \'no\' end as on_time_delivery, po_type, case when po_type is null or po_type = \'\' then null when po_type in (\'job\', \'fob\', \'efob\') and grn_receive_quantity >= (0.99 * po_original_quantity) then \'yes\' else \'no\' end as in_fill, grn_created_date as first_grn_date from maplemonk.saadaa_po_grn_mapping ), po_level_returns as ( select coalesce(g.po, f.po) as po_ref_num, sum(r.no_of_times_returned) as customer_return_qty from ( select upper(replace(serial_number,\'`\',\'\')) as serial_number, sku, count(distinct original_putaway_datetime) as no_of_times_returned from maplemonk.saadaa_easyecom_putaway_report where lower(putawaytype) like \'%return putaway%\' group by 1, 2 ) r left join ( select upper(replace(serial_number,\'`\',\'\')) as serial_number, po from maplemonk.saadaa_serial_out_of_system_report qualify row_number() over (partition by upper(replace(serial_number,\'`\',\'\')) order by 1) = 1 ) g on r.serial_number = g.serial_number left join ( select upper(replace(serial_number,\'`\',\'\')) as serial_number, po from maplemonk.easyecom_full_inventory_report qualify row_number() over (partition by upper(replace(serial_number,\'`\',\'\')) order by 1) = 1 ) f on r.serial_number = f.serial_number where coalesce(g.po, f.po) is not null group by 1 ), po_level_qc as ( select po, sum(qc_fail_quantity) as total_qc_fail_qty, sum(qc_pass_quantity) as qc_pass_quantity from maplemonk.saadaa_easyecom_qc_report where po <> \'\' or grn <> \'\' group by 1 ) select p.*, case when lower(on_time_delivery) = \'yes\' and lower(in_fill) = \'yes\' then \'yes\' when on_time_delivery is null or in_fill is null then null else \'no\' end as otiff, case when lower(on_time_delivery) like \'no\' then date_diff(date(last_grn_date),date(expected_delivery_date),day) end as delay_days, cast(c.total_cutting_qty as int64) as cutting_register_qty, case when po_type is null or po_type = \'\' then null when po_type in (\'job\', \'fob\', \'efob\') and grn_receive_quantity >= (0.99 * cast(c.total_cutting_qty as int64)) then \'yes\' else \'no\' end as in_fill_cutting_register, case when on_time_delivery is null or po_type is null or po_type = \'\' then null when on_time_delivery = \'yes\' and (po_type in (\'job\', \'fob\', \'efob\') and grn_receive_quantity >= (0.99 * cast(c.total_cutting_qty as int64))) then \'yes\' else \'no\' end as otiff_cutting_register, coalesce(ret.customer_return_qty, 0) as customer_return_qty, coalesce(qc.total_qc_fail_qty, 0) as total_qc_fail_qty from po_data p left join maplemonk.otiff_sheet8 c on trim(upper(p.po_ref_num)) = trim(upper(c.po_number)) left join po_level_returns ret on trim(upper(p.po_id)) = trim(upper(ret.po_ref_num)) left join po_level_qc qc on trim(upper(p.po_id)) = trim(upper(qc.po)) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
